
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_tpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_tpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.717340262362798e+00, -4.621931657296145e+00, -4.488212068556348e+00, -4.302922042796706e+00, -4.050345892057095e+00, -3.714066886747392e+00, -3.281320924566837e+00, -2.751625264312292e+00, -2.151969344763561e+00, -1.555557071437572e+00, -1.033814048696274e+00, -6.936518814308644e-01, -6.016133634365598e-01, -5.114304227079262e-01, -3.666163024326402e-01, -2.314535955491643e-01, -1.313605321997716e-01, -4.950390693588704e-02, -1.081191816544374e-02, -1.216202148314421e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


